import {MUSHROOMS} from './assets/mushrooms.js';
function nameIconMap(sessions){const icons=new Map(),used=new Set(),names=[...new Set(sessions.map(s=>s.name||'自由記錄'))].sort();for(const name of names){let hash=2166136261;for(const char of name)hash=Math.imul(hash^char.codePointAt(0),16777619)>>>0;let index=hash%MUSHROOMS.length;for(let step=0;step<MUSHROOMS.length&&used.has(index);step++)index=(index+1)%MUSHROOMS.length;used.add(index);icons.set(name,MUSHROOMS[index].id);}return icons;}
export function activityRows(sessions,batches,allSessions=sessions){const rows=new Map(),byID=new Map(batches.map(b=>[b.id,b])),icons=nameIconMap([...allSessions,...sessions]);for(const session of sessions){const name=session.name||'自由記錄';let row=rows.get(name);if(!row){row={name,seconds:0,times:0,mushrooms:0,icon:icons.get(name)};rows.set(name,row);}row.seconds+=session.seconds;row.times++;const batch=byID.get(session.id);if(batch)row.mushrooms+=batch.count;}return [...rows.values()];}
